#ifndef MAINWINDOW_H
#define MAINWINDOW_H

#include <QWidget>

// Forward declarations to reduce header dependencies
class QLineEdit;
class QPushButton;
class QTextEdit;

class MainWindow : public QWidget
{
    Q_OBJECT

public:
    MainWindow(QWidget *parent = nullptr);
    ~MainWindow();

private slots:
    void onSelectDirectoryClicked();
    void onConvertClicked();

private:
    void log(const QString &message);
    void performConversion();
    QString escapeCsv(const QString &input);

    // UI Elements
    QLineEdit *directoryPathEdit;
    QPushButton *selectDirButton;
    QPushButton *convertButton;
    QTextEdit *logOutput;
};

#endif // MAINWINDOW_H
```

