#include "QXlsx/xlsxdocument.h"

MainWindow::MainWindow(QWidget *parent)
    : QWidget(parent)
{
    // --- Setup UI ---
    setWindowTitle("Excel to CSV Converter");
    setMinimumSize(500, 400);

    directoryPathEdit = new QLineEdit();
    directoryPathEdit->setPlaceholderText("Select a directory containing Excel files...");
    directoryPathEdit->setReadOnly(true);

    selectDirButton = new QPushButton("Select Directory");
    convertButton = new QPushButton("Convert to CSV");
    logOutput = new QTextEdit();
    logOutput->setReadOnly(true);

    // --- Layout ---
    QHBoxLayout *topLayout = new QHBoxLayout();
    topLayout->addWidget(directoryPathEdit);
    topLayout->addWidget(selectDirButton);

    QVBoxLayout *mainLayout = new QVBoxLayout();
    mainLayout->addLayout(topLayout);
    mainLayout->addWidget(logOutput);
    mainLayout->addWidget(convertButton);
    setLayout(mainLayout);

    // --- Connections ---
    connect(selectDirButton, &QPushButton::clicked, this, &MainWindow::onSelectDirectoryClicked);
    connect(convertButton, &QPushButton::clicked, this, &MainWindow::onConvertClicked);

    log("Welcome! Please select a directory to begin.");
}

MainWindow::~MainWindow() {}

void MainWindow::log(const QString &message)
{
    logOutput->append(message);
}

void MainWindow::onSelectDirectoryClicked()
{
    QString directory = QFileDialog::getExistingDirectory(this, 
        "Select Folder", 
        directoryPathEdit->text());

    if (!directory.isEmpty()) {
        directoryPathEdit->setText(directory);
        log(QString("Selected directory: %1").arg(directory));
    }
}

void MainWindow::onConvertClicked()
{
    QString dirPath = directoryPathEdit->text();
    if (dirPath.isEmpty()) {
        QMessageBox::warning(this, "Error", "Please select a directory first.");
        return;
    }

    // Disable the button to prevent multiple clicks while processing
    convertButton->setEnabled(false);
    log("\n----- Starting Conversion -----");

    performConversion();

    log("----- Conversion Finished -----");
    QMessageBox::information(this, "Success", "Conversion process has finished. Check the log for details.");

    // Re-enable the button
    convertButton->setEnabled(true);
}

void MainWindow::performConversion()
{
    QDir sourceDir(directoryPathEdit->text());
    QString outputFolderName = "csv_output";

    // Create the output directory
    if (!sourceDir.exists(outputFolderName)) {
        if (sourceDir.mkdir(outputFolderName)) {
            log(QString("Created output directory: %1").arg(outputFolderName));
        } else {
            log(QString("Error: Could not create output directory: %1").arg(outputFolderName));
            return;
        }
    }

    QString outputDirPath = sourceDir.absoluteFilePath(outputFolderName);

    // Filter for Excel files
    QStringList filters;
    filters << "*.xlsx" << "*.xls";
    sourceDir.setNameFilters(filters);

    QStringList excelFiles = sourceDir.entryList(QDir::Files);

    if (excelFiles.isEmpty()) {
        log("No Excel files (.xlsx, .xls) found in the selected directory.");
        return;
    }

    for (const QString &excelFile : excelFiles) {
        QString inputFilePath = sourceDir.absoluteFilePath(excelFile);
        QFileInfo fileInfo(excelFile);
        QString outputFileName = fileInfo.baseName() + ".csv";
        QString outputFilePath = QDir(outputDirPath).absoluteFilePath(outputFileName);

        log(QString("Converting %1 -> %2...").arg(excelFile, outputFileName));

        // Use QXlsx to read the document
        QXlsx::Document xlsx(inputFilePath);
        if (!xlsx.load()) {
            log(QString("Error: Could not open file %1").arg(excelFile));
            continue;
        }

        // Open the output CSV file for writing
        QFile csvFile(outputFilePath);
        if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
            log(QString("Error: Could not create output file %1").arg(outputFileName));
            continue;
        }

        QTextStream out(&csvFile);

        // Assuming we only convert the first sheet
        xlsx.selectSheet(xlsx.sheetNames().at(0));
        QXlsx::CellRange range = xlsx.dimension();
        int maxRow = range.lastRow();
        int maxCol = range.lastColumn();

        for (int row = 1; row <= maxRow; ++row) {
            QStringList rowData;
            for (int col = 1; col <= maxCol; ++col) {
                QXlsx::Cell* cell = xlsx.cellAt(row, col);
